edits.sketch:
for _, c := range readableProvocations {
	var v gateVerdict
	checkForm(c, &v)
	if !v.fatal() {
		return c
	}
}
t.Fatal("no provocation in the post-rail corpus clears the deterministic layers, ...")

if !v.Approved && onlyFatalRuleIs(v, "hard_to_read") {
	railOnly++
	return
}
// ...
if railOnly != 8 {
	t.Errorf("expected exactly 8 pre-rail entries to fail ONLY on readability, found %d", railOnly)
}

var consulted bool
if tc.judgeSays != nil {
	inner := judgeReturning(*tc.judgeSays)
	judge = func(ctx context.Context, prompt string) (string, error) {
		consulted = true
		return inner(ctx, prompt)
	}
}
// ...
if tc.judgeSays != nil && !consulted {
	t.Fatalf("%s never reached the judge, so this case cannot test %q", tc.name, tc.wantRule)
}
